script.setup:
const gl=ctx.gl;
const vs=`#version 300 es
in vec2 p;void main(){gl_Position=vec4(p,0.,1.);}`;
const fs=`#version 300 es
precision highp float;
uniform vec2 uRes;uniform float uAngle;out vec4 o;
void main(){
 vec2 uv=(gl_FragCoord.xy-.5*uRes)/min(uRes.x,uRes.y);
 float r=length(uv);float a=atan(uv.y,uv.x)+uAngle;
 float arms=4.;
 float s=sin(arms*a+log(r+1e-3)*9.);
 float band=smoothstep(.0,.9,s*.5+.5);
 vec3 deep=vec3(.08,.02,.15);
 vec3 purple=vec3(.62,.25,.95);
 vec3 light=vec3(.9,.7,1.);
 vec3 c=mix(deep,purple,band);
 c=mix(c,light,pow(band,6.)*.6);
 c*=smoothstep(1.1,.05,r);
 c+=vec3(.5,.2,.8)*.06/(r+.06);
 o=vec4(c,1.);
}`;
function sh(t,s){const x=gl.createShader(t);gl.shaderSource(x,s);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(x));return x;}
const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);
if(!gl.getProgramParameter(pr,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(pr));
const vao=gl.createVertexArray();gl.bindVertexArray(vao);
const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
const loc=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
ctx.state={pr,vao,uRes:gl.getUniformLocation(pr,'uRes'),uAngle:gl.getUniformLocation(pr,'uAngle'),angle:0,last:null};

script.render:
const gl=ctx.gl,s=ctx.state;
const t=ctx.time;const dt=s.last===null?0:Math.max(0,Math.min(0.1,t-s.last));s.last=t;
const u=ctx.uniforms||{};const sp=(u.u_speed&&typeof u.u_speed==='object')?u.u_speed.value:u.u_speed;
s.angle+=(sp??0.3)*dt;
gl.useProgram(s.pr);gl.bindVertexArray(s.vao);
gl.uniform2f(s.uRes,gl.drawingBufferWidth,gl.drawingBufferHeight);
gl.uniform1f(s.uAngle,s.angle);
gl.drawArrays(gl.TRIANGLES,0,3);
